SELECT 'batch_002_9349782e_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0c73cb05-35e','sm-upload-2ee8f752-0ca','sm-upload-481244dd-64a','sm-upload-5cb2b5d2-c80','sm-upload-6204a4fa-7d4','sm-upload-62e99b99-1d9','sm-upload-a6899ade-703','sm-upload-ada463c4-049','sm-upload-ae0d532d-833','sm-upload-b84182f5-1a9') AND album_id='al-71bf81052233fba89504b82c9349782e') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0c73cb05-35e','sm-upload-2ee8f752-0ca','sm-upload-481244dd-64a','sm-upload-5cb2b5d2-c80','sm-upload-6204a4fa-7d4','sm-upload-62e99b99-1d9','sm-upload-a6899ade-703','sm-upload-ada463c4-049','sm-upload-ae0d532d-833','sm-upload-b84182f5-1a9') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-71bf81052233fba89504b82c9349782e' AND name='忘川风华录·溯洄') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-71bf81052233fba89504b82c9349782e') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-71bf81052233fba89504b82c9349782e') AS calculated_size;
